const catalog = $('Fetch Schema-only Catalog').first().json.message;
const raw = $input.all().flatMap((item) => {
  if (Array.isArray(item.json)) return item.json;
  if (Array.isArray(item.json.body)) return item.json.body;
  return item.json && item.json.doctype ? [item.json] : [];
});
const existing = new Map(raw.map((row) => [`${row.doctype}\u0000${row.chunk_id}`, row.content_hash]));
const desired = catalog.doctypes.flatMap((entry) => entry.chunks.map((chunk) => ({ site_id: catalog.site_id, doctype: entry.doctype, ...chunk })));
const desiredKeys = new Set(desired.map((chunk) => `${chunk.doctype}\u0000${chunk.chunk_id}`));
const changed = desired.filter((chunk) => existing.get(`${chunk.doctype}\u0000${chunk.chunk_id}`) !== chunk.content_hash);
const deleted = raw.filter((row) => !desiredKeys.has(`${row.doctype}\u0000${row.chunk_id}`)).map((row) => ({ doctype: row.doctype, chunk_id: row.chunk_id }));
return [{ json: { catalog, changed, deleted, hasChanges: changed.length ? 'yes' : 'no' } }];

const responses = $input.all();
const source = $('Changed Schema Chunks').all().map((item) => item.json);
const embedded = [];
const errors = [];
for (let index = 0; index < source.length; index++) {
  const response = responses[index]?.json || {};
  const status = Number(response.statusCode || 200);
  const body = response.body || response;
  const values = body?.embeddings?.[0]?.values || body?.embedding?.values;
  if (status < 200 || status >= 300 || !Array.isArray(values) || values.length !== Number($env.AI_EMBEDDING_DIMENSIONS || 768)) {
    errors.push(`${source[index].doctype}/${source[index].chunk_id}: embedding failed (${status})`);
    continue;
  }
  embedded.push({ ...source[index], embedding: values, embedding_model: $env.AI_EMBEDDING_MODEL });
}
return [{ json: { route: errors.length ? 'error' : 'ok', error: errors.join('; ').slice(0, 4000), chunks: embedded } }];

const status = Number($json.statusCode || 200);
const ok = status >= 200 && status < 300;
return [{ json: { route: ok ? 'ok' : 'error', error: ok ? '' : `Atomic Supabase upsert failed (${status})` } }];

const status = Number($json.statusCode || 200);
const ok = status >= 200 && status < 300;
return [{ json: { route: ok ? 'ok' : 'error', error: ok ? '' : `Atomic stale deletion failed (${status})` } }];

const comparison = $('Compare Deterministic Hashes').first().json;
const changedCount = comparison.changed.length;
const deletedCount = comparison.deleted.length;
return [{ json: { result: { status: changedCount || deletedCount ? 'Drift' : 'Success', catalog_hash: comparison.catalog.catalog_hash, doctype_count: comparison.catalog.doctype_count, chunk_count: comparison.catalog.chunk_count, changed_count: changedCount, deleted_count: deletedCount, error: '' } } }];

let catalog = {};
let comparison = { changed: [], deleted: [] };
try { catalog = $('Fetch Schema-only Catalog').first().json.message || {}; } catch {}
try { comparison = $('Compare Deterministic Hashes').first().json || comparison; } catch {}
const rawError = $json.error || (typeof $json.message === 'string' ? $json.message : '') || '';
let error = typeof rawError === 'object' ? (rawError.message || JSON.stringify(rawError)) : String(rawError);
if (!catalog.complete && Array.isArray(catalog.errors)) error = `Catalog incomplete: ${catalog.errors.map((entry) => `${entry.doctype}: ${entry.error}`).join('; ')}`;
return [{ json: { result: { status: 'Error', catalog_hash: catalog.catalog_hash || '', doctype_count: catalog.doctype_count || 0, chunk_count: catalog.chunk_count || 0, changed_count: comparison.changed?.length || 0, deleted_count: 0, error: String(error || 'Schema synchronization failed before completion').slice(0, 4000) } } }];

const input = $('Permissioned Query Input').first().json;
const question = typeof input.query === 'string' ? input.query.trim() : '';
if (!question) throw new Error('A natural-language read request is required.');
const dateContext = $('Validate Session Before Retrieval').first().json?.message?.date_context;
const currentDate = String(dateContext?.current_date || '');
const currentYear = Number(dateContext?.current_year);
const datePattern = /^\d{4}-\d{2}-\d{2}$/;
if (!datePattern.test(currentDate) || !Number.isInteger(currentYear) || currentYear !== Number(currentDate.slice(0, 4)) || dateContext?.current_year_start !== `${currentYear}-01-01` || dateContext?.current_year_end !== `${currentYear}-12-31` || !datePattern.test(String(dateContext?.current_month_start || '')) || !datePattern.test(String(dateContext?.current_month_end || '')) || typeof dateContext?.time_zone !== 'string' || !dateContext.time_zone || dateContext.time_zone.length > 64) throw new Error('Frappe returned an invalid authoritative date context.');
const rawSql = /```(?:sql|mysql|mariadb|postgresql)?/i.test(question) || /(?:^|[\s;(])(?:select\s+.+?\s+from|insert\s+into|update\s+[^\s;]+\s+set|delete\s+from|drop\s+(?:table|database)|alter\s+table|truncate\s+table|create\s+(?:table|database|index)|grant\s+|revoke\s+|merge\s+into|exec(?:ute)?\s+|call\s+)/is.test(question) || /\b(?:from|join)\s+[`\"']?(?:tab[A-Za-z0-9_]+|__[A-Za-z0-9_]+)/i.test(question) || /\b(?:union\s+select|information_schema|pg_catalog|frappe\.db\.sql|cursor\.execute)\b/i.test(question);
const writeIntent = /^(?:please\s+)?(?:delete|remove|erase|update|change|edit|modify|insert|create|add|write|set)\b/i.test(question) || /^(?:請|请)?(?:刪除|删除|移除|更新|修改|新增|建立|创建|寫入|写入)/.test(question);
const sensitiveRequest = /\b(?:password|passphrase|api[ -]?key|secret|access[ -]?token|session[ -]?id|credential|cookie)\b/i.test(question) || /(?:密碼|密码|口令|金鑰|金钥|密鑰|密钥|秘鑰|秘钥|權杖|令牌|憑證|凭证)/.test(question);
const injectionAttempt = /\b(?:ignore|disregard|override|bypass)\b.{0,50}\b(?:instruction|prompt|permission|security|policy|rule)\b/is.test(question) || /\b(?:jailbreak|act as (?:an? )?(?:administrator|admin|root)|developer mode)\b/i.test(question);
if (rawSql || writeIntent || sensitiveRequest || injectionAttempt) throw new Error('Only safe natural-language, read-only ERPNext questions are accepted.');
return [{ json: { question, dateContext } }];

const validated = $('Validate Natural-language Read Request').first().json;
const question = validated.question;
const dateContext = validated.dateContext;
const matches = $input.all().flatMap((item) => Array.isArray(item.json) ? item.json : [item.json]);
if (!matches.length) throw new Error('No allowlisted schema metadata matched this question.');
const schema = matches.map((row) => row.content).filter(Boolean).join('

---

');
const contract = { version: '1', doctype: 'ONE allowlisted DocType', fields: ['fieldname'], filters: [{ field: 'fieldname', operator: '=', value: 'value' }], order_by: [{ field: 'fieldname', direction: 'asc' }], offset: 0, limit: 20, aggregates: [{ function: 'count|sum|average|minimum|maximum', field: '* or fieldname' }], group_by: ['fieldname'] };
const temporalContext = `Current ERPNext date: ${dateContext.current_date}
Current ERPNext year: ${dateContext.current_year}
Current-year range: ${dateContext.current_year_start} through ${dateContext.current_year_end}
Current-month range: ${dateContext.current_month_start} through ${dateContext.current_month_end}
ERPNext time zone: ${dateContext.time_zone}`;
const prompt = `Convert the user's ERPNext data question into QueryPlanV1 JSON. Return JSON only. Never return SQL, code, writes, joins, expressions, or more than one DocType. Use only DocTypes and fields present in the supplied schema. Resolve ordinary natural-language business names, translated labels, and abbreviations against the supplied DocType name, label, and description; for example, a business phrase may validly refer to an allowlisted DocType without using its exact technical name. Do not invent an unrelated DocType or field. The AUTHORITATIVE ERPNext DATE CONTEXT below is server-supplied and overrides model knowledge, training dates, and prior conversation. Resolve relative time phrases in every language against it. In particular, this year, current year, 今年, and 本年 mean exactly ${dateContext.current_year_start} through ${dateContext.current_year_end}. Today means ${dateContext.current_date}. This month means exactly ${dateContext.current_month_start} through ${dateContext.current_month_end}. Never guess the current date or year. Use explicit date filters when the question is relative to time. Supported filter operators: =, !=, >, >=, <, <=, in, not in, like, not like, between, is. Keep limit at or below 100. For ordinary lists omit aggregates and group_by. For aggregates, fields may contain only group_by fields. Contract example: ${JSON.stringify(contract)}

AUTHORITATIVE ERPNEXT DATE CONTEXT:
${temporalContext}

SCHEMA METADATA ONLY:
${schema}

USER QUESTION:
${question}`;
return [{ json: { prompt } }];

const text = $json?.candidates?.[0]?.content?.parts?.map((part) => part.text || '').join('') || '';
const cleaned = text.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
let plan;
try { plan = JSON.parse(cleaned); } catch { throw new Error('Gemini did not return valid QueryPlanV1 JSON.'); }
if (!plan || Array.isArray(plan) || typeof plan !== 'object') throw new Error('QueryPlanV1 must be a JSON object.');
const input = $('Permissioned Query Input').first().json;
return [{ json: { queryPlan: JSON.stringify(plan), sessionToken: input.sessionToken, sessionId: input.sessionId } }];

const result = $json.message;
if (!result || !Array.isArray(result.rows)) throw new Error('Frappe returned an invalid query result.');
let notice = '';
if (result.truncated) notice = ` Results were truncated to ${result.limit} rows; ask for the next page using offset ${result.offset + result.limit}.`;
return [{ json: { output: JSON.stringify({ ...result, notice }) } }];

const metadata = $json.metadata;
const sessionToken = metadata?.aiSessionToken;
const sessionId = $json.sessionId;
const metadataSessionId = metadata?.aiSessionId;
if ($json.action !== 'sendMessage' || typeof $json.chatInput !== 'string' || !$json.chatInput.trim()) throw new Error('A valid chat message is required.');
if (typeof sessionToken !== 'string' || sessionToken.length < 32 || sessionToken.length > 256) throw new Error('A valid ERPNext browser session is required.');
if (typeof sessionId !== 'string' || sessionId.length < 24 || sessionId.length > 256 || sessionId !== metadataSessionId) throw new Error('A valid ERPNext browser session is required.');
return [{ json: { ...$json, sessionToken, sessionId } }];

const input = $('Capture Browser Auth Context').first().json;
const question = input.chatInput.trim();
const dateContext = $('Validate Frappe Session Before Gemini').first().json?.message?.date_context;
const currentDate = String(dateContext?.current_date || '');
const currentYear = Number(dateContext?.current_year);
const datePattern = /^\d{4}-\d{2}-\d{2}$/;
if (!datePattern.test(currentDate) || !Number.isInteger(currentYear) || currentYear !== Number(currentDate.slice(0, 4)) || dateContext?.current_year_start !== `${currentYear}-01-01` || dateContext?.current_year_end !== `${currentYear}-12-31` || !datePattern.test(String(dateContext?.current_month_start || '')) || !datePattern.test(String(dateContext?.current_month_end || '')) || typeof dateContext?.time_zone !== 'string' || !dateContext.time_zone || dateContext.time_zone.length > 64) throw new Error('Frappe returned an invalid authoritative date context.');
const hasChinese = /[\u3400-\u9fff]/.test(question);
const rawSql = /```(?:sql|mysql|mariadb|postgresql)?/i.test(question) || /(?:^|[\s;(])(?:select\s+.+?\s+from|insert\s+into|update\s+[^\s;]+\s+set|delete\s+from|drop\s+(?:table|database)|alter\s+table|truncate\s+table|create\s+(?:table|database|index)|grant\s+|revoke\s+|merge\s+into|exec(?:ute)?\s+|call\s+)/is.test(question) || /\b(?:from|join)\s+[`\"']?(?:tab[A-Za-z0-9_]+|__[A-Za-z0-9_]+)/i.test(question) || /\b(?:union\s+select|information_schema|pg_catalog|frappe\.db\.sql|cursor\.execute)\b/i.test(question);
const writeIntent = /^(?:please\s+)?(?:delete|remove|erase|update|change|edit|modify|insert|create|add|write|set)\b/i.test(question) || /\b(?:can|could|would|will)\s+you\s+(?:please\s+)?(?:delete|remove|erase|update|change|edit|modify|insert|create|add|write|set)\b/i.test(question) || /^(?:請|请)?(?:刪除|删除|移除|更新|修改|新增|建立|创建|寫入|写入)/.test(question);
const sensitiveRequest = /\b(?:password|passphrase|api[ -]?key|secret|access[ -]?token|session[ -]?id|credential|cookie)\b/i.test(question) || /(?:密碼|密码|口令|金鑰|金钥|密鑰|密钥|秘鑰|秘钥|權杖|令牌|憑證|凭证)/.test(question);
const injectionAttempt = /\b(?:ignore|disregard|override|bypass)\b.{0,50}\b(?:instruction|prompt|permission|security|policy|rule)\b/is.test(question) || /\b(?:jailbreak|act as (?:an? )?(?:administrator|admin|root)|developer mode)\b/i.test(question) || /(?:忽略|繞過|绕过).{0,30}(?:指令|權限|权限|安全|規則|规则)/.test(question);
let rejection = '';
if (rawSql) {
  rejection = hasChinese
    ? '基於安全考慮，我不能執行原始 SQL，也不能把系統資料表改寫成其他允許的資料查詢。請用自然語言詢問「Schema DocType Allowlist」中已啟用的業務資料。'
    : 'For security, I cannot execute raw SQL or redirect a system-table request to other allowed data. Ask in natural language about business data enabled in the Schema DocType Allowlist.';
} else if (writeIntent) {
  rejection = hasChinese
    ? '此助理只提供唯讀查詢，不能新增、修改或刪除 ERPNext 資料。'
    : 'This assistant is read-only and cannot create, change, or delete ERPNext data.';
} else if (sensitiveRequest) {
  rejection = hasChinese
    ? '我不能擷取或透露密碼、API 金鑰、權杖、Cookie 或其他憑證。'
    : 'I cannot retrieve or disclose passwords, API keys, tokens, cookies, or other credentials.';
} else if (injectionAttempt) {
  rejection = hasChinese
    ? '此要求嘗試繞過助理的安全或權限規則，因此已被拒絕。'
    : 'This request attempts to bypass assistant safety or permission rules and was rejected.';
}
return [{ json: { route: rejection ? 'reject' : 'allow', rejection, dateContext } }];
